Now the instruction pool and the checkers. Each instruction has a text, a checker applied to the final answer (the text after the last </think>), and conflict tags so incompatible pairs are never combined (for example JSON with quotation wrapping, or lowercase with uppercase). I'll test the checkers on hand-made strings at the end of the block. If any obvious case is judged wrongly, I'll fix that checker before going on.

```python
# Hypothesis: none -- instruction pool + checkers, tested on toy strings.
def words(s): return re.findall(r"[A-Za-z0-9]+(?:'[A-Za-z]+)?", s)
def sentences(s):
    parts = re.split(r'(?<=[.!?])\s+', s.strip())
    return [p for p in parts if re.search(r'[A-Za-z0-9]', p)]
def strip_json_fence(s):
    s = s.strip()
    m = re.match(r'^`{3}(?:json|JSON)?\s*\n?(.*?)\n?`{3}$', s, re.S)
    return m.group(1) if m else s

KW_POOL = ['window','silver','harvest','journey','lantern','garden','thunder','balance','whisper','compass','meadow','engine',
           'feather','mirror','orchard','candle','bridge','harbor','puzzle','velvet','anchor','canyon','ribbon','marble']
WORD_POOL = ['light','home','together','bright','again','dream','road','heart','time','song']
END_PHRASES = ['That is all for today.', 'Thank you for reading.', 'Until we meet again.', 'And that is the whole story.', 'Let me know what you think.']
START_WORDS = ['Indeed','Today','Listen','Once','Well']

def make_instruction(kind, task, r):
    if kind=='words_min':
        n = r.choice([150,200,250,300,400,500]); return (f"Your response should contain at least {n} words.", lambda a,n=n: len(words(a))>=n)
    if kind=='words_max':
        n = r.choice([60,80,100,120,150,200]); return (f"Your response should contain at most {n} words.", lambda a,n=n: 0<len(words(a))<=n)
    if kind=='sent_min':
        n = r.choice([8,10,12,15,20]); return (f"Your response should contain at least {n} sentences.", lambda a,n=n: len(sentences(a))>=n)
    if kind=='sent_max':
        n = r.choice([3,4,5,6,8]); return (f"Your answer must contain at most {n} sentences.", lambda a,n=n: 0<len(sentences(a))<=n)
    if kind=='paragraphs':
        n = r.choice([2,3,4,5]); return (f"There should be exactly {n} paragraphs. Paragraphs are separated from each other by the markdown divider: ***",
            lambda a,n=n: len([p for p in re.split(r'\n\s*\*\*\*\s*\n', a.strip()) if p.strip()])==n and a.count('***')==n-1)
    if kind=='keywords':
        ks = r.sample(KW_POOL, 2); return (f"Include the keywords '{ks[0]}' and '{ks[1]}' in your response.",
            lambda a,ks=ks: all(re.search(r'\b'+k+r'\b', a, re.I) for k in ks))
    if kind=='word_freq':
        w = r.choice(WORD_POOL); n = r.choice([3,4,5,6]); return (f"Use the word '{w}' at least {n} times.",
            lambda a,w=w,n=n: len(re.findall(r'\b'+w+r'\b', a, re.I))>=n)
    if kind=='end_phrase':
        p = r.choice(END_PHRASES); return (f"Finish your response with this exact phrase: '{p}'. No other words should follow it.", lambda a,p=p: a.strip().endswith(p))
    if kind=='postscript':
        return ("At the end of your response, please explicitly add a postscript starting with P.S.", lambda a: re.search(r'(^|\n)\s*P\.\s?S\.', a, re.I) is not None)
    if kind=='lowercase':
        return ("Your entire response should be in English, and in all lowercase letters. No capital letters are allowed.", lambda a: a==a.lower() and re.search('[a-z]',a) is not None)
    if kind=='uppercase':
        return ("Your entire response should be in English and in all capital letters.", lambda a: a==a.upper() and re.search('[A-Z]',a) is not None)
    if kind=='no_commas':
        return ("In your entire response, refrain from the use of any commas.", lambda a: ',' not in a and len(a.strip())>0)
    if kind=='quotation':
        return ("Wrap your entire response with double quotation marks.", lambda a: len(a.strip())>1 and a.strip()[0]=='"' and a.strip()[-1]=='"')
    if kind=='json':
        def cj(a):
            try: json.loads(strip_json_fence(a)); return True
            except Exception: return False
        return ("Entire output should be wrapped in JSON format. You can use markdown ticks such as ```.".replace('```', '`'*3), cj)
    if kind=='title':
        return ("Your answer must contain a title, wrapped in double angular brackets, such as <<my title>>.", lambda a: re.search(r'<<[^\n<>]+>>', a) is not None)
    if kind=='highlights':
        n = r.choice([2,3,4]); return (f"Highlight at least {n} sections in your answer with markdown, i.e. *highlighted section*.", lambda a,n=n: len(re.findall(r'\*[^\n\*]+\*', a))>=n)
    if kind=='bullets':
        n = r.choice([3,4,5]); return (f"Your answer must contain exactly {n} bullet points. Use the markdown bullet points such as:\n* This is point 1.",
            lambda a,n=n: len(re.findall(r'^\s*[\*\-] ', a, re.M))==n)
    if kind=='repeat':
        return ("First repeat the request word for word without change, then give your answer (1. do not say any words or characters before repeating the request; 2. the request you need to repeat does not include this sentence)",
            lambda a,t=task: a.strip().lower().startswith(t.strip().lower()))
    if kind=='two_resp':
        def c2(a):
            parts = a.split('******')
            return len(parts)==2 and all(p.strip() for p in parts) and parts[0].strip()!=parts[1].strip()
        return ("Give two different responses. Responses and only responses should be separated by 6 asterisk symbols: ******.", c2)
    if kind=='placeholders':
        n = r.choice([2,3,4]); return (f"The response must contain at least {n} placeholders represented by square brackets, such as [address].", lambda a,n=n: len(re.findall(r'\[[^\[\]\n]+\]', a))>=n)
    if kind=='sections':
        n = r.choice([2,3,4]); return (f"Your response must have {n} sections. Mark the beginning of each section with SECTION X, such as: SECTION 1",
            lambda a,n=n: len(re.findall(r'(?:^|\n)\s*\**\s*SECTION\s+\d+', a))==n)
    if kind=='start_word':
        w = r.choice(START_WORDS); return (f"Start your response with the word '{w}'.", lambda a,w=w: re.match(r'^\W*'+w+r'\b', a.strip()) is not None)
    raise ValueError(kind)

KINDS = ['words_min','words_max','sent_min','sent_max','paragraphs','keywords','word_freq','end_phrase','postscript','lowercase','uppercase',
         'no_commas','quotation','json','title','highlights','bullets','repeat','two_resp','placeholders','sections','start_word']
CONFLICT = {
 'json': set(KINDS)-{'json','keywords','lowercase','words_min','words_max','word_freq','no_commas'},
 'quotation': {'json','repeat','two_resp','end_phrase','start_word','postscript'},
 'lowercase': {'uppercase','sections','title','start_word'},
 'uppercase': {'lowercase','repeat','start_word','end_phrase','keywords','word_freq'},
 'words_min': {'words_max','sent_max'}, 'words_max': {'words_min','sent_min'},
 'sent_min': {'sent_max','words_max'}, 'sent_max': {'sent_min','words_min'},
 'end_phrase': {'postscript','quotation','two_resp'}, 'postscript': {'end_phrase','quotation'},
 'repeat': {'start_word','quotation','two_resp','json','uppercase'}, 'start_word': {'repeat','quotation','lowercase','uppercase'},
 'two_resp': {'json','quotation','repeat','paragraphs','sections','end_phrase'},
 'paragraphs': {'json','two_resp','sections','bullets'}, 'sections': {'json','two_resp','paragraphs','lowercase'},
 'bullets': {'json','paragraphs'},
}
def conflicts(a,b): return b in CONFLICT.get(a,set()) or a in CONFLICT.get(b,set())

# toy tests
r0 = random.Random(0)
t_ok = []
_, c = make_instruction('postscript','x',r0); t_ok.append(c("hello\nP.S. bye")); t_ok.append(not c("hello"))
_, c = make_instruction('quotation','x',r0); t_ok.append(c('"hi there"')); t_ok.append(not c('hi'))
_, c = make_instruction('json','x',r0); t_ok.append(c('`'*3+'json\n{"a": 1}\n'+'`'*3)); t_ok.append(not c('{a:1'))
_, c = make_instruction('paragraphs','x',random.Random(5)); print(_); t_ok.append(c("a\n***\nb\n***\nc") or c("a\n***\nb") or c("a\n***\nb\n***\nc\n***\nd") or c("a\n***\nb\n***\nc\n***\nd\n***\ne"))
_, c = make_instruction('sections','x',random.Random(1)); print(_); t_ok.append(c("SECTION 1\nfoo\nSECTION 2\nbar") or c("SECTION 1\nfoo\nSECTION 2\nbar\nSECTION 3\nbaz") or c("SECTION 1\nfoo\nSECTION 2\nbar\nSECTION 3\nbaz\nSECTION 4\nq"))
_, c = make_instruction('two_resp','x',r0); t_ok.append(c("one\n******\ntwo")); t_ok.append(not c("one"))
_, c = make_instruction('repeat','Write a poem.',r0); t_ok.append(c("Write a poem.\n\nRoses...")); t_ok.append(not c("Sure! Write a poem."))
_, c = make_instruction('bullets','x',random.Random(2)); print(_); 
print(t_ok, len(sentences("Hi there. I am here! Are you? Yes")), len(words("It's a dog-day, 12 cats.")))
```

The prose set is built: 1,200 prompts, 721 of them loop-prone. Next is the ten-option multiple-choice set. To be sure of every answer key, most questions are computed (physics, chemistry, finance and economics, probability and combinatorics, number bases, genetics, heat and unit conversions). The nine distractors are formatted the same way as the answer and include typical slips (factor of 2, wrong formula). I'll add a smaller set of knowledge questions I'm sure of. The prompt asks the model to think step by step and finish with "The answer is (X)", like the held-out suite. Grading takes the last "answer is (X)" after the last </think>.

```python
# Hypothesis: none -- programmatic 10-option MC questions with verified keys.
LET = 'ABCDEFGHIJ'
def fmt(x, nd):
    if nd == 0: return f"{int(round(x))}"
    return f"{x:.{nd}f}"
def numeric_opts(ans, r, nd=2, unit='', extra=()):
    cands = [ans*f for f in (0.5,2,1.5,0.75,1.25,0.8,1.2,0.9,1.1,3,0.25,4,0.6,1.4)] + list(extra)
    vals = []
    a_s = fmt(ans, nd)
    seen = {a_s}
    r.shuffle(cands)
    for c in list(extra) + cands:
        s = fmt(c, nd)
        if s not in seen and (abs(c) > 0 or ans==0):
            seen.add(s); vals.append(s)
        if len(vals) == 9: break
    k = 1
    while len(vals) < 9:
        s = fmt(ans + k*(10**-nd if nd>0 else 1)*r.choice([1,-1])*r.randint(1,9), nd)
        if s not in seen: seen.add(s); vals.append(s)
        k += 1
    opts = vals + [a_s]
    r.shuffle(opts)
    u = (' '+unit) if unit else ''
    return [o+u for o in opts], opts.index(a_s)

def g_kin(r):
    v0=r.randint(0,20); a=r.randint(1,9); t=r.randint(2,12)
    d=v0*t+0.5*a*t*t
    q=f"A car moving at {v0} m/s accelerates uniformly at {a} m/s^2 for {t} s. How far does it travel during this time?"
    return 'physics', q, *numeric_opts(d, r, 1, 'm', extra=(v0*t+a*t*t, a*t*t/2, v0*t))
def g_proj(r):
    v=r.choice([10,12,14,15,18,20,24,25,30]); g=9.8
    h=v*v/(2*g)
    q=f"A ball is thrown straight up with a speed of {v} m/s. Ignoring air resistance and taking g = 9.8 m/s^2, what is its maximum height?"
    return 'physics', q, *numeric_opts(h, r, 2, 'm', extra=(v*v/g, v/g))
def g_ohm(r):
    V=r.choice([6,9,12,18,24,120,230]); R=r.choice([2,3,4,5,6,8,10,12,15,20,30,47,100])
    P=V*V/R
    q=f"A resistor of {R} ohms is connected across a {V} V source. What power does it dissipate?"
    return 'physics', q, *numeric_opts(P, r, 2, 'W', extra=(V/R, V*R, V*V*R/1000))
def g_par(r):
    a,b,c=r.sample([2,3,4,5,6,8,10,12,15,20,24,30],3)
    R=1/(1/a+1/b+1/c)
    q=f"Three resistors of {a}, {b} and {c} ohms are connected in parallel. What is the equivalent resistance?"
    return 'physics', q, *numeric_opts(R, r, 2, 'ohms', extra=(a+b+c, (a+b+c)/3))
def g_ke(r):
    m=r.choice([0.5,1,2,3,4,5,10,20,50,1200]); v=r.randint(2,30)
    K=0.5*m*v*v
    q=f"What is the kinetic energy of a {m} kg object moving at {v} m/s?"
    return 'physics', q, *numeric_opts(K, r, 1, 'J', extra=(m*v*v, m*v))
def g_mom(r):
    m1=r.randint(1,10); v1=r.randint(1,15); m2=r.randint(1,10)
    v=m1*v1/(m1+m2)
    q=f"A {m1} kg cart moving at {v1} m/s collides with and sticks to a stationary {m2} kg cart. What is their common speed after the collision?"
    return 'physics', q, *numeric_opts(v, r, 2, 'm/s', extra=(m1*v1/m2, v1/2))
def g_wave(r):
    f=r.choice([50,100,200,256,440,500,1000]); lam=r.choice([0.5,0.68,0.75,1.2,1.5,2,3.4])
    q=f"A wave has frequency {f} Hz and wavelength {lam} m. What is its speed?"
    return 'physics', q, *numeric_opts(f*lam, r, 1, 'm/s', extra=(f/lam, lam/f))
def g_heat(r):
    m=r.choice([0.2,0.5,1,1.5,2,3]); dT=r.randint(5,60); c=r.choice([(4186,'water'),(900,'aluminum'),(385,'copper'),(450,'iron')])
    Q=m*c[0]*dT
    q=f"How much heat is needed to raise the temperature of {m} kg of {c[1]} by {dT} degrees Celsius? (specific heat {c[0]} J/(kg K))"
    return 'engineering', q, *numeric_opts(Q, r, 0, 'J', extra=(m*c[0], c[0]*dT))
def g_molar(r):
    comps={'H2O':18.015,'CO2':44.009,'NaCl':58.44,'CaCO3':100.086,'C6H12O6':180.156,'H2SO4':98.079,'NH3':17.031,'CH4':16.043,'KCl':74.551,'MgO':40.304,'NaOH':39.997,'HCl':36.458}
    k=r.choice(list(comps)); m=r.choice([5,10,18,25,36,50,72,100,150,200])
    n=m/comps[k]
    q=f"How many moles are there in {m} g of {k}? (Use standard atomic masses.)"
    return 'chemistry', q, *numeric_opts(n, r, 3, 'mol', extra=(m*comps[k]/1000, comps[k]/m))
def g_gas(r):
    n=r.choice([0.5,1,1.5,2,2.5,3]); T=r.choice([273,298,300,350,400]); V=r.choice([5,10,15,20,22.4,25])
    P=n*0.08206*T/V
    q=f"What is the pressure of {n} mol of an ideal gas at {T} K in a {V} L container? (R = 0.08206 L atm / (mol K))"
    return 'chemistry', q, *numeric_opts(P, r, 2, 'atm', extra=(n*8.314*T/V/100, n*T/V))
def g_dil(r):
    C1=r.choice([0.5,1,2,3,6,12]); V1=r.choice([10,20,25,50,100]); V2=r.choice([200,250,500,1000])
    C2=C1*V1/V2
    q=f"{V1} mL of a {C1} M solution is diluted to a final volume of {V2} mL. What is the new concentration?"
    return 'chemistry', q, *numeric_opts(C2, r, 3, 'M', extra=(C1*V2/V1/100, C1*V1/(V1+V2)))
def g_ph(r):
    e=r.randint(1,6); c=r.choice([1,2,5])
    import math
    pH=-math.log10(c*10**(-e))
    q=f"What is the pH of a {c}x10^-{e} M solution of a strong monoprotic acid?"
    return 'chemistry', q, *numeric_opts(pH, r, 2, '', extra=(e, 14-pH, pH+1))
def g_cint(r):
    P=r.choice([1000,2000,2500,5000,10000]); rate=r.choice([2,3,4,5,6,7,8]); t=r.randint(2,15)
    A=P*(1+rate/100)**t
    q=f"An investment of ${P} earns {rate}% interest per year, compounded annually. What is it worth after {t} years?"
    return 'economics', q, *numeric_opts(A, r, 2, '', extra=(P*(1+rate*t/100), P*rate*t/100))
def g_pct(r):
    a=r.randint(20,500); b=a+r.choice([-1,1])*r.randint(5,a-5)
    p=(b-a)/a*100
    q=f"The price of a good changes from ${a} to ${b}. What is the percentage change in price?"
    return 'economics', q, *numeric_opts(p, r, 2, '%', extra=((b-a)/b*100, -p))
def g_be(r):
    F=r.choice([1000,2400,5000,12000,30000]); p=r.randint(15,80); vc=r.randint(5,p-5)
    n=F/(p-vc)
    q=f"A firm has fixed costs of ${F}. Each unit sells for ${p} and has a variable cost of ${vc}. How many units must it sell to break even?"
    return 'economics', q, *numeric_opts(n, r, 1, 'units', extra=(F/p, F/vc))
def g_elas(r):
    p1=r.randint(5,20); p2=p1+r.randint(1,5); q1=r.randint(100,400); q2=q1-r.randint(10,90)
    e=((q2-q1)/((q1+q2)/2))/((p2-p1)/((p1+p2)/2))
    q=f"When the price rises from ${p1} to ${p2}, the quantity demanded falls from {q1} to {q2}. Using the midpoint method, what is the price elasticity of demand?"
    return 'economics', q, *numeric_opts(e, r, 2, '', extra=(-e, ((q2-q1)/q1)/((p2-p1)/p1)))
def g_prob(r):
    a=r.randint(2,6); b=r.randint(2,6); k=r.randint(1,min(a,3))
    from math import comb
    p=comb(a,k)*comb(b,3-k)/comb(a+b,3) if 3-k<=b else 0
    q=f"A bag has {a} red and {b} blue marbles. Three are drawn without replacement. What is the probability that exactly {k} are red?"
    return 'math', q, *numeric_opts(p, r, 3, '', extra=(comb(3,k)*(a/(a+b))**k*(b/(a+b))**(3-k),))
def g_comb(r):
    n=r.randint(6,14); k=r.randint(2,5)
    from math import comb, perm
    q=f"In how many ways can a committee of {k} people be chosen from {n} people?"
